import{at as e,n as t,rt as n,xt as r}from"./chunks/framework.DIOWbp6D.js";var i=JSON.parse(`{"title":"kernel","description":"","frontmatter":{},"headers":[],"relativePath":"kernel/index.md","filePath":"vendored/kernel/index.md"}`),a={name:`kernel/index.md`};function o(t,i,a,o,s,c){return r(),n(`div`,null,[...i[0]||=[e(`<h1 id="kernel" tabindex="-1">kernel <a class="header-anchor" href="#kernel" aria-label="Permalink to “kernel”">​</a></h1><p>The arrow-calculus substrate: language schema, tagged values, extension ABI.</p><h2 id="what-it-is" tabindex="-1">What it is <a class="header-anchor" href="#what-it-is" aria-label="Permalink to “What it is”">​</a></h2><p>The kernel is the platform&#39;s smallest layer (ADR-0040): the <code>Language</code> data schema and staged <code>lex</code>/<code>parse</code>/<code>eval</code> dispatch signatures (ADR-0044, language as data), the tagged <code>Value</code> representation the engines share, and the dynamic extension ABI (<code>hnl</code> extensions, ADR-0149). Libraries live in their own <code>lib-*</code> repos.</p><p>What is <em>not</em> kernel: engines, emitters, kits, plugins and hosts. They live in the <code>engine-*</code>/<code>tool-*</code>/<code>exec-*</code>, <code>kit-*</code>, <code>ext-*</code> and <code>host</code>/<code>host-*</code> repos and depend on the kernel, never the reverse.</p><h2 id="modules" tabindex="-1">Modules <a class="header-anchor" href="#modules" aria-label="Permalink to “Modules”">​</a></h2><ul><li><code>crates/handl-calculus</code> — the arrow-calculus IR (<code>Term</code>/<code>TermData</code>, <code>Model</code>/<code>ModelCtx</code>)</li><li><code>crates/handl-language</code> — the <code>Language</code> schema + staged lex/parse/eval dispatch signatures</li><li><code>crates/handl-value</code> — the tagged <code>Value</code> representation shared by engines</li><li><code>crates/handl-ops</code> — the op ABI (<code>Op</code>/<code>OpRegistry</code>/<code>OpContext</code>)</li><li><code>crates/handl-ext</code> — the shared ABI for dynamic <code>hnl</code> extensions (ADR-0149)</li><li><code>crates/defining-handl</code> — the self-hosting corpus (ADR-0044 phase 8)</li><li><code>crates/{ops,prim,prim-handl}</code> — the remaining <code>handl-lib-*</code> substrate packages</li></ul><h2 id="start-here" tabindex="-1">Start here <a class="header-anchor" href="#start-here" aria-label="Permalink to “Start here”">​</a></h2><ul><li><strong>Reference</strong> — <a href="/docs/kernel/reference/">public API</a></li><li><strong>How-to</strong> — <a href="/docs/kernel/how-to/">task recipes</a></li><li><strong>Explanation</strong> — <a href="/docs/kernel/explanation/">design and rationale</a></li></ul><p>No tutorials: this repo is a building block used from Rust. End-to-end walkthroughs live with the product that composes it — see the <a href="/docs/handl/">Handl platform</a>.</p>`,10)]])}var s=t(a,[[`render`,o]]);export{i as __pageData,s as default};